/**
 * Authoring helpers for eval/traps-v2. The dataset file traps.json is generated by build.mjs from
 * the project files in this directory and then frozen; nothing here is read by the harness.
 */

/** One session: user, assistant, user, assistant ... (always ends with an assistant message). */
export const S = (...turns) => {
  if (turns.length < 2 || turns.length % 2 !== 0) throw new Error('a session needs an even number of turns: ' + String(turns[0]).slice(0, 40));
  return turns;
};

const lcg = (seed) => { let s = seed >>> 0; return () => { s = (Math.imul(s, 1664525) + 1013904223) >>> 0; return s / 2 ** 32; }; };
const pick = (r, list) => list[Math.floor(r() * list.length)];
const two = (n) => String(n).padStart(2, '0');

const GENERATORS = {
  // application log lines
  app: (r, i, o) => {
    const t = `2026-09-12T02:${two(Math.floor(i / 60) % 60)}:${two(i % 60)}.${String(Math.floor(r() * 1000)).padStart(3, '0')}Z`;
    if (i % 9 === 4) return `${t} ERROR [${o.svc}] batch=${1000 + i} upstream request failed: ECONNRESET after ${Math.floor(r() * 9000)}ms (attempt ${1 + (i % 3)}/3)`;
    if (i % 13 === 7) return `${t} WARN  [${o.svc}] batch=${1000 + i} slow step=${pick(r, ['fetch', 'diff', 'write'])} elapsed=${2000 + Math.floor(r() * 6000)}ms`;
    return `${t} INFO  [${o.svc}] batch=${1000 + i} fetched=${Math.floor(r() * 900)} matched=${Math.floor(r() * 900)} elapsed=${Math.floor(r() * 900)}ms`;
  },
  // Postgres / ClickHouse style slow query log
  db: (r, i) => `2026-09-12 03:${two(Math.floor(i / 60) % 60)}:${two(i % 60)} UTC [${20000 + i}] LOG:  duration: ${1200 + Math.floor(r() * 9000)}.${Math.floor(r() * 900)} ms  statement: SELECT t.id, t.amount, t.updated_at FROM ${pick(r, ['ledger_entries', 'invoices', 'events_raw', 'device_state'])} t WHERE t.updated_at > $1 AND t.shard = ${Math.floor(r() * 16)} ORDER BY t.updated_at LIMIT ${100 * (1 + Math.floor(r() * 9))}`,
  // build / CI output
  ci: (r, i) => `##[group]Run step ${i}: ${pick(r, ['pnpm install --frozen-lockfile', 'pnpm -r build', 'pnpm -r test -- --reporter=dot', 'pnpm lint', 'docker build -t app:ci .'])}\n   ${pick(r, ['Progress: resolved', 'transforming', 'rendering chunks', 'computing gzip size'])} ${Math.floor(r() * 3000)} modules, done in ${(r() * 20).toFixed(1)}s ${i % 11 === 5 ? '\n   FAIL  src/' + pick(r, ['orders', 'import', 'export', 'auth']) + '.test.ts > case ' + i + '\n   AssertionError: expected ' + Math.floor(r() * 90) + ' to equal ' + Math.floor(r() * 90) : ''}`,
  // stack traces
  stack: (r, i, o) => `    at ${pick(r, ['processTicksAndRejections', 'Object.run', 'async Worker.handle', 'async Pool.query', 'async ' + o.svc + '.step'])} (${pick(r, ['node:internal/process/task_queues:95:5', '/app/dist/' + o.svc + '/worker.js:' + (30 + i) + ':' + (3 + (i % 40)), '/app/node_modules/pg-pool/index.js:45:11', '/app/dist/db/client.js:' + (88 + i) + ':17'])})`,
};

/** A pasted block of about `chars` characters (generated, deterministic). */
export function paste(kind, chars, seed = 1, svc = 'worker') {
  const r = lcg(seed * 7919 + chars);
  const lines = [];
  let total = 0;
  for (let i = 0; total < chars; i += 1) {
    const line = GENERATORS[kind](r, i, { svc });
    lines.push(line);
    total += line.length + 1;
  }
  return lines.join('\n');
}
